[
  {
    "statement": "Planting nectar flower mixture or wildflower strips provides essential nectar sources and habitat for butterflies and moths.",
    "citations": [
      "3932"
    ]
  },
  {
    "statement": "Studies show that nectar flower mixture or wildflower strips have higher species richness and abundance of butterflies and moths compared to conventional field margins, cropped fields, or grass-only margins.",
    "citations": [
      "3932"
    ]
  },
  {
    "statement": "Organic farms show greater species richness and abundance of butterflies and burnet moths compared to conventional farms.",
    "citations": [
      "3907"
    ]
  },
  {
    "statement": "The abundance of butterflies and burnet moths on organic farms increases with time since conversion from conventional farming.",
    "citations": [
      "3907"
    ]
  },
  {
    "statement": "Farms with greater proportions of semi-natural habitat or woodland in surrounding areas support higher species richness and abundance.",
    "citations": [
      "3910"
    ]
  },
  {
    "statement": "Wider grass buffer margins, up to 6 meters, and floristically enhanced grass buffers show higher abundance and species richness compared to cropped field edges.",
    "citations": [
      "3982"
    ]
  },
  {
    "statement": "Grasslands cut once in July or September show greater abundance of butterflies and burnet moths than grasslands cut in May or June.",
    "citations": [
      "3967"
    ]
  },
  {
    "statement": "Grasslands with staggered mowing or rotational management have higher species richness and abundance compared to grasslands with annual full-site mowing.",
    "citations": [
      "3966"
    ]
  },
  {
    "statement": "Unsprayed conservation headlands show greater species richness and abundance of butterflies compared to sprayed headlands.",
    "citations": [
      "3898"
    ]
  },
  {
    "statement": "Longer or wider uncultivated margins that are not cut, or are only cut in spring or autumn, support higher species richness and abundance compared to summer-cut margins.",
    "citations": [
      "3981"
    ]
  }
]

[
  {
    "statement": "Alternative management strategies to prescribed burning for maintaining open grassland habitats for butterflies include rotational mowing, changing mowing regimes, grazing management, mechanical vegetation removal, and herbicide application.",
    "citations": []
  },
  {
    "statement": "Rotational mowing, which involves mowing strips in alternate years or leaving some areas uncut, can increase butterfly species richness and abundance compared to annual complete mowing.",
    "citations": []
  },
  {
    "statement": "Delaying grassland cutting dates to July or September rather than May or June can increase butterfly abundance.",
    "citations": []
  },
  {
    "statement": "Changing mowing regimes, such as mowing in August versus November, can maintain caterpillar populations.",
    "citations": []
  },
  {
    "statement": "Intensive grazing generally reduces butterfly abundance compared to light or no grazing.",
    "citations": []
  },
  {
    "statement": "Traditional low-intensity grazing can be beneficial for butterfly populations.",
    "citations": []
  },
  {
    "statement": "Mechanical removal of mid-storey or ground vegetation and herbicide application are additional alternatives to prescribed burning.",
    "citations": []
  },
  {
    "statement": "Evidence for the effectiveness of mechanical vegetation removal and herbicide application specifically for butterflies is limited.",
    "citations": []
  },
  {
    "statement": "Maintaining species-rich semi-natural grasslands through extensive management, such as light grazing or annual mowing, can support butterfly communities.",
    "citations": []
  }
]

[
  {
    "statement": "Studies have documented several benefits of habitat connectivity for butterfly populations.",
    "citations": []
  },
  {
    "statement": "Retaining connectivity between habitat patches helps butterfly populations persist.",
    "citations": []
  },
  {
    "statement": "Well-connected low quality habitat patches are more likely to retain Alcon large blue populations than less well connected patches.",
    "citations": []
  },
  {
    "statement": "Habitat corridors facilitate the movement of butterflies.",
    "citations": []
  },
  {
    "statement": "Common buckeye butterflies were more likely to colonize distant habitat patches when released on corridors of suitable habitat.",
    "citations": []
  },
  {
    "statement": "Restoring or creating habitat connectivity has been shown to increase the abundance of multiple butterfly species, including Karner blue, high brown fritillary, small pearl-bordered fritillary, marsh fritillary, and regal fritillary butterflies.",
    "citations": []
  },
  {
    "statement": "Connected habitat patches promote movement of butterflies between patches.",
    "citations": []
  },
  {
    "statement": "Common buckeye and variegated fritillary butterflies are more likely to move between connected patches than unconnected patches.",
    "citations": []
  },
  {
    "statement": "Grassland strips providing nectar or shelter were more likely to be used by butterfly species than strips with no resources.",
    "citations": []
  }
]

[
  {
    "statement": "Multiple UK studies demonstrate that reducing management intensity on permanent grasslands significantly benefits butterfly and moth populations.",
    "citations": []
  },
  {
    "statement": "Cutting strips of grassland in alternate years or leaving rotational areas uncut increases butterfly and burnet moth abundance compared to annual complete mowing.",
    "citations": [
      "1"
    ]
  },
  {
    "statement": "Two heath fritillary populations survived on rotationally mown grasslands.",
    "citations": [
      "1"
    ]
  },
  {
    "statement": "Six heath fritillary populations went extinct on unmanaged grasslands.",
    "citations": [
      "1"
    ]
  },
  {
    "statement": "Mowing grassland once in July instead of May or June increases butterfly abundance and species richness.",
    "citations": [
      "2"
    ]
  },
  {
    "statement": "Cutting grassland in September maintains stable populations of the scarce large blue butterfly.",
    "citations": [
      "2"
    ]
  },
  {
    "statement": "Mowing grassland in May led to decreases in scarce large blue butterfly populations over time.",
    "citations": [
      "2"
    ]
  },
  {
    "statement": "Unfertilized UK grasslands support greater species richness of specialist moths compared to fertilized grasslands.",
    "citations": [
      "3"
    ]
  },
  {
    "statement": "Unfertilized UK grasslands support a similar abundance of adult butterflies compared to fertilized grasslands.",
    "citations": [
      "3"
    ]
  },
  {
    "statement": "On road verges and greenspaces, less frequent mowing or leaving areas unmown increases butterfly species richness and abundance compared to regularly mown areas.",
    "citations": [
      "4"
    ]
  },
  {
    "statement": "In the UK, 24 out of 58 moth species prefer less intensively managed grasslands.",
    "citations": []
  },
  {
    "statement": "Reducing grazing combined with stopping chemical applications increased both the species richness and total abundance of large moths.",
    "citations": []
  }
]

[
  {
    "statement": "Reducing or eliminating chemical inputs on farmland provides significant benefits for butterflies and moths.",
    "citations": []
  },
  {
    "statement": "Areas managed with less frequent, reduced, or no pesticide, herbicide, fertilizer, or unspecified chemical inputs had greater species richness of adult butterflies and moths, or caterpillars, compared to areas with more frequent or conventional chemical applications.",
    "citations": [
      "3897"
    ]
  },
  {
    "statement": "Arable field margins and rice field banks that were not sprayed with herbicides like glyphosate had greater species richness of butterflies than sprayed areas.",
    "citations": [
      "3896"
    ]
  },
  {
    "statement": "Arable field margins and rice field banks that were not sprayed with herbicides like glyphosate had a higher abundance of butterflies than sprayed areas.",
    "citations": [
      "3896"
    ]
  },
  {
    "statement": "Converting to organic farming showed benefits for butterflies and moths.",
    "citations": [
      "3907"
    ]
  },
  {
    "statement": "Organic farms had greater species richness of butterflies and moths than conventionally managed farms.",
    "citations": [
      "3907"
    ]
  },
  {
    "statement": "Organic farms had a greater abundance of butterflies and moths than conventionally managed farms.",
    "citations": [
      "3907"
    ]
  },
  {
    "statement": "The benefits of reducing chemical inputs on farmland included overall increases in butterfly and moth populations.",
    "citations": []
  },
  {
    "statement": "Specific butterfly and moth species have preferences for unfertilized or lightly fertilized grasslands over heavily fertilized ones.",
    "citations": []
  }
]

[
  {
    "statement": "Thinning trees within forests is an evidence-based alternative to prescribed burning for managing forest disturbance to benefit butterflies.",
    "citations": []
  },
  {
    "statement": "Studies in the USA and Finland found that thinned coniferous woodland had greater species richness and abundance of butterflies compared to unmanaged woodland.",
    "citations": []
  },
  {
    "statement": "Clearing or opening patches in forests is an evidence-based alternative to prescribed burning for managing forest disturbance to benefit butterflies.",
    "citations": []
  },
  {
    "statement": "Studies across multiple countries found that cleared forest patches had greater species richness and abundance of butterflies than unmanaged patches or closed canopy forest.",
    "citations": []
  },
  {
    "statement": "Clearing or opening patches in forests benefits butterfly species such as the chequered blue, woodland brown, high brown fritillary, and small pearl-bordered fritillary.",
    "citations": []
  },
  {
    "statement": "Coppicing woodland is an evidence-based alternative to prescribed burning for managing forest disturbance to benefit butterflies.",
    "citations": []
  },
  {
    "statement": "Multiple studies found that coppiced woodland had a higher abundance of butterflies compared to unmanaged woodland.",
    "citations": []
  },
  {
    "statement": "Coppicing woodland specifically benefits species such as the heath fritillary.",
    "citations": []
  },
  {
    "statement": "The optimal benefits for butterflies from coppicing occur 2 to 7 years after the woodland is coppiced.",
    "citations": []
  },
  {
    "statement": "Creating young plantations within mature woodland is an evidence-based alternative to prescribed burning to benefit butterflies.",
    "citations": []
  },
  {
    "statement": "A UK study found that woodlands with larger areas of young plantations helped pearl-bordered fritillary and small pearl-bordered fritillary populations persist longer than in mature woodland.",
    "citations": []
  }
]

[
  {
    "statement": "Management actions for traditional orchards and vineyards in the USA and Germany have been studied for their effects on butterflies and moths.",
    "citations": []
  },
  {
    "statement": "Maintaining traditional orchards for butterflies and moths has been evaluated in studies in the USA and Germany.",
    "citations": []
  },
  {
    "statement": "A German study found that managed orchards had similar species richness of butterflies and burnet moths compared to abandoned orchards.",
    "citations": []
  },
  {
    "statement": "The German study found that managed orchards had a lower abundance of butterflies and burnet moths compared to abandoned orchards.",
    "citations": []
  },
  {
    "statement": "The German study found a similar community composition of butterflies and moths between managed and abandoned orchards.",
    "citations": []
  },
  {
    "statement": "A USA study found that unmanaged and partially managed orchards had greater species richness and diversity of leaf-eating arthropods, including caterpillars, than commercially managed orchards.",
    "citations": []
  },
  {
    "statement": "The management of vineyards for butterflies and moths has been evaluated in studies in the USA and Spain.",
    "citations": []
  },
  {
    "statement": "A USA study found that grass strips between vine rows had greater butterfly species richness than the vine rows themselves.",
    "citations": []
  },
  {
    "statement": "A USA study found that vineyards using fewer chemicals had greater butterfly species richness than conventionally managed vineyards.",
    "citations": []
  },
  {
    "statement": "Another USA study found that vineyards managed to encourage native plants with rare insecticide use had greater butterfly abundance than conventionally managed vineyards.",
    "citations": []
  },
  {
    "statement": "Studies in the USA and Germany have evaluated the effects of reducing the use of fertilizer, pesticide, or herbicide.",
    "citations": []
  },
  {
    "statement": "Orchards, crop edges, farms, vineyards, and agricultural landscapes managed with reduced or no chemical inputs had greater species richness of adult butterflies, moths, or caterpillars compared to areas with conventional chemical applications.",
    "citations": []
  },
  {
    "statement": "Orchards, crop edges, farms, vineyards, and agricultural landscapes managed with reduced or no chemical inputs had greater abundance of adult butterflies, moths, or caterpillars compared to areas with conventional chemical applications.",
    "citations": []
  },
  {
    "statement": "Converting to organic farming has been evaluated in thirteen studies, including one study in Germany.",
    "citations": []
  },
  {
    "statement": "Multiple studies found that organic farms had greater species richness of butterflies and moths than conventional farms.",
    "citations": []
  },
  {
    "statement": "Multiple studies found that organic farms had greater abundance of butterflies and moths than conventional farms.",
    "citations": []
  }
]

[
  {
    "statement": "Several grazing management strategies show beneficial effects for butterfly species richness in European grasslands.",
    "citations": []
  },
  {
    "statement": "Reducing grazing intensity by lowering stocking density appears to be one of the most beneficial strategies for butterfly species richness.",
    "citations": [
      "3959"
    ]
  },
  {
    "statement": "Grasslands grazed with lower stocking densities of sheep, cattle or mixed livestock had greater species richness of adult butterflies, all moths and burnet moths compared to grasslands with higher stocking densities.",
    "citations": [
      "3959"
    ]
  },
  {
    "statement": "Seasonal removal of livestock shows benefits for butterfly richness.",
    "citations": [
      "3960"
    ]
  },
  {
    "statement": "Grasslands where cattle or sheep were removed during summer months had similar or greater species richness of butterflies compared to continuously grazed grasslands.",
    "citations": [
      "3960"
    ]
  },
  {
    "statement": "Rotational grazing demonstrates positive effects for the species richness of butterflies and burnet moths.",
    "citations": [
      "3965"
    ]
  },
  {
    "statement": "Rotationally grazed grasslands had greater species richness of butterflies and burnet moths than continuously grazed grasslands.",
    "citations": [
      "3965"
    ]
  },
  {
    "statement": "The results of rotational grazing on butterfly and burnet moth species richness varied by stocking density and study duration.",
    "citations": [
      "3965"
    ]
  },
  {
    "statement": "Changing livestock type can benefit butterfly richness.",
    "citations": [
      "3963"
    ]
  },
  {
    "statement": "Semi-natural grasslands grazed by cattle or horses had greater species richness of butterflies and burnet moths than sheep-grazed grasslands.",
    "citations": [
      "3963"
    ]
  },
  {
    "statement": "Increasing grazing intensity or cutting frequency generally shows negative effects on butterflies.",
    "citations": [
      "3962"
    ]
  },
  {
    "statement": "Intensively grazed sites had lower species richness and abundance of butterflies compared to sites with low or no grazing.",
    "citations": [
      "3962"
    ]
  },
  {
    "statement": "Ceasing grazing entirely produces mixed results for butterfly richness.",
    "citations": [
      "3956"
    ]
  },
  {
    "statement": "Some studies show increased butterfly richness after 4-10 years of grassland abandonment.",
    "citations": [
      "3956"
    ]
  },
  {
    "statement": "Some studies show abandoned grasslands have similar or reduced butterfly richness compared to grazed grasslands.",
    "citations": [
      "3956"
    ]
  }
]

[
  {
    "statement": "Butterfly communities have been observed responding to grassland management changes across multiple timeframes.",
    "citations": []
  },
  {
    "statement": "Following grassland abandonment, studies have documented butterfly community responses over timeframes ranging from 1-6 years, 3-13 years, and 10-20 years.",
    "citations": []
  },
  {
    "statement": "Butterfly community responses to grassland abandonment have been documented over timeframes of more than 50 years.",
    "citations": []
  },
  {
    "statement": "One study tracked butterfly community changes over 6 years following grassland abandonment.",
    "citations": []
  },
  {
    "statement": "Studies have examined butterfly responses following grassland restoration efforts.",
    "citations": []
  },
  {
    "statement": "The specific timeframes for butterfly responses to restoration efforts have varied between studies.",
    "citations": []
  },
  {
    "statement": "One study found that restored semi-natural grasslands did not become more similar to existing species-rich grasslands over time following restoration.",
    "citations": []
  },
  {
    "statement": "Studies have tracked butterfly responses to changes in management intensity.",
    "citations": []
  },
  {
    "statement": "Butterfly responses have been tracked for management changes that include rotational grazing.",
    "citations": []
  },
  {
    "statement": "Butterfly responses have been tracked for reduced management intensity approaches.",
    "citations": []
  }
]

[
  {
    "statement": "Research has shown several alternative management practices for field margins and headlands that benefit butterfly populations on UK farmland beyond sowing wildflower mixes.",
    "citations": []
  },
  {
    "statement": "Conservation headlands, which involves leaving headlands unsprayed, have been shown to increase both butterfly species richness and abundance compared to sprayed headlands.",
    "citations": []
  },
  {
    "statement": "Studies have found greater species richness of butterflies in unsprayed headlands.",
    "citations": []
  },
  {
    "statement": "Studies have found a higher abundance of butterflies and caterpillars in unsprayed headlands.",
    "citations": []
  },
  {
    "statement": "Hedgerow management practices, including planting new hedges and managing existing hedgerows for wildlife, have demonstrated significant benefits.",
    "citations": []
  },
  {
    "statement": "Planting new hedges has been found to result in higher species richness of butterflies and macro-moths compared to crops or pasture.",
    "citations": []
  },
  {
    "statement": "A higher abundance of butterflies, moths and gatekeepers is found along hedgerows.",
    "citations": []
  },
  {
    "statement": "Managing hedgerows by cutting them once every 2-3 years has shown a higher abundance of adult butterflies and moths.",
    "citations": []
  },
  {
    "statement": "Managing hedgerows by cutting them in autumn rather than winter has shown a higher abundance of adult butterflies and moths.",
    "citations": []
  },
  {
    "statement": "Hedgerows containing trees support a higher abundance of butterflies than simple hedgerows.",
    "citations": []
  },
  {
    "statement": "Creating uncultivated margins around fields has shown benefits, including higher species richness of butterflies in longer or wider margins.",
    "citations": []
  },
  {
    "statement": "Creating uncultivated margins around fields has shown a higher abundance of butterflies compared to cereal fields.",
    "citations": []
  },
  {
    "statement": "Grass buffer strips planted around fields have been found effective when the strips are wider, up to 6 meters wide.",
    "citations": []
  },
  {
    "statement": "Floristically enhanced grass buffers show greater species richness of butterflies than standard grass margins.",
    "citations": []
  },
  {
    "statement": "Floristically enhanced grass buffers show greater abundance of butterflies than standard grass margins.",
    "citations": []
  },
  {
    "statement": "Leaving uncropped, cultivated margins can increase the abundance of some butterfly species.",
    "citations": []
  },
  {
    "statement": "Buffer strips designed to reduce pesticide run-off have been shown to increase moth abundance compared to conventionally managed margins.",
    "citations": []
  },
  {
    "statement": "Proper cutting management of margins results in higher species richness and abundance of butterflies.",
    "citations": []
  },
  {
    "statement": "Cutting margins only in spring or autumn rather than summer results in higher species richness and abundance of butterflies.",
    "citations": []
  }
]

[
  {
    "statement": "The evidence shows that butterfly and moth populations respond to woodland coppicing and clearing over various timeframes.",
    "citations": []
  },
  {
    "statement": "For coppicing, butterfly and moth abundance was higher in woodland coppiced 2-4 years ago compared to older coppice of 5-11 years or more than 15 years.",
    "citations": []
  },
  {
    "statement": "Woodland coppiced 2 years ago had greater butterfly species richness than woodland coppiced more than 15 years ago.",
    "citations": []
  },
  {
    "statement": "For clearing patches in forests, patches cleared 2-4 years ago had a greater abundance of heath fritillary butterflies than patches cleared 7-11 years ago.",
    "citations": []
  },
  {
    "statement": "For clearing patches in forests, patches cleared 2-4 years ago had a greater abundance of heath fritillary butterflies than patches in their first year after clearance.",
    "citations": []
  },
  {
    "statement": "Butterfly species richness declined over the first three years after clearing.",
    "citations": []
  },
  {
    "statement": "Butterfly abundance initially increased before declining over the first three years after clearing.",
    "citations": []
  },
  {
    "statement": "The evidence suggests that butterfly and moth populations typically respond positively 2-4 years after management.",
    "citations": []
  },
  {
    "statement": "The responses of butterfly and moth populations can vary by species.",
    "citations": []
  },
  {
    "statement": "The positive response of butterfly and moth populations can decline as vegetation ages beyond the 2-4 year timeframe after management.",
    "citations": []
  }
]

[
  {
    "statement": "Several alternative actions can increase habitat heterogeneity within agricultural fields for butterflies and moths.",
    "citations": []
  },
  {
    "statement": "Reducing field size or maintaining small fields has been shown to increase both species richness and abundance of butterflies and burnet moths compared to landscapes with larger fields.",
    "citations": [
      "3974"
    ]
  },
  {
    "statement": "Creating beetle banks, which are raised strips within arable fields, can increase micro-moth species richness and abundance compared to conventionally managed field margins.",
    "citations": [
      "3927"
    ]
  },
  {
    "statement": "Planting new hedges within agricultural landscapes provides habitat with higher species richness and abundance of butterflies and moths compared to crop fields or pasture.",
    "citations": [
      "3976"
    ]
  },
  {
    "statement": "Leaving unharvested crop headlands within arable fields can create habitat with greater butterfly species richness and abundance than harvested crops.",
    "citations": [
      "3924"
    ]
  },
  {
    "statement": "Leaving uncropped, cultivated margins or plots within fields can increase butterfly abundance, particularly when managed under agri-environment schemes.",
    "citations": [
      "3923"
    ]
  },
  {
    "statement": "Planting wildflower strips or nectar flower mixtures within fields significantly increases both species richness and abundance of butterflies and moths compared to conventional field margins or cropped fields.",
    "citations": [
      "3932"
    ]
  },
  {
    "statement": "Increasing overall crop diversity across the farmed landscape, while showing mixed results, represents another approach to creating habitat heterogeneity within agricultural systems.",
    "citations": [
      "3921"
    ]
  }
]

[
  {
    "statement": "Based on studies in US prairies, prescribed burning has mixed effects on butterfly abundance compared to other management techniques.",
    "citations": []
  },
  {
    "statement": "Prairies managed by haying had a higher abundance of prairie specialist butterflies than prairies managed by burning.",
    "citations": [
      "3945",
      "3882"
    ]
  },
  {
    "statement": "Prairies managed by burning had a lower abundance of two prairie specialists, the regal fritillary and arogos skipper, compared to prairies managed by haying.",
    "citations": [
      "3882"
    ]
  },
  {
    "statement": "Prairies managed by burning had a higher abundance of generalist and migrant species compared to hayed prairies.",
    "citations": []
  },
  {
    "statement": "For rotational burning, prairies burned more than one to four years ago had a higher total abundance of prairie specialist, grassland, and all butterflies compared to prairies burned more recently.",
    "citations": [
      "3883"
    ]
  },
  {
    "statement": "The abundance of the regal fritillary was higher in rotationally burned prairies four years after the last burn compared to one or eight years after burning.",
    "citations": []
  },
  {
    "statement": "Grazing combined with rotational burning showed variable results for butterfly abundance.",
    "citations": [
      "3908"
    ]
  },
  {
    "statement": "Some studies found higher butterfly abundance in grazed areas compared to burned areas, while other studies found similar or lower abundance depending on the specific butterfly species examined.",
    "citations": [
      "3908"
    ]
  }
]

[
  {
    "statement": "Within European agri-environment schemes, planting nectar flower mixtures or wildflower strips is a habitat creation option shown to consistently increase butterfly and moth abundance.",
    "citations": []
  },
  {
    "statement": "Within European agri-environment schemes, managing hedgerows to benefit wildlife is a habitat creation option shown to consistently increase butterfly and moth abundance.",
    "citations": []
  },
  {
    "statement": "Wildflower strips consistently demonstrated higher butterfly and moth abundance across multiple studies.",
    "citations": []
  },
  {
    "statement": "Multiple studies showed significantly higher butterfly and moth abundance in wildflower strips when compared to conventional field margins or cropped fields.",
    "citations": []
  },
  {
    "statement": "Hedgerow management involving less frequent cutting consistently increased butterfly and moth abundance.",
    "citations": []
  },
  {
    "statement": "Less frequent cutting of hedgerows includes cutting every 2-3 years or cutting in the autumn.",
    "citations": []
  },
  {
    "statement": "Maintaining a complex structure in hedgerows consistently increased butterfly and moth abundance.",
    "citations": []
  },
  {
    "statement": "Creating uncultivated margins showed more variable results for increasing butterfly and moth abundance.",
    "citations": []
  },
  {
    "statement": "Planting wild bird seed mixtures showed more variable results for increasing butterfly and moth abundance.",
    "citations": []
  },
  {
    "statement": "The effects of creating uncultivated margins and planting wild bird seed mixtures on butterflies and moths are less consistent across studies.",
    "citations": []
  }
]

[
  {
    "statement": "Several management practices in perennial crop systems can benefit butterfly and moth conservation.",
    "citations": []
  },
  {
    "statement": "In coffee plantations, shade-grown systems support higher species richness of caterpillars compared to sun-grown monocultures.",
    "citations": [
      "3931"
    ]
  },
  {
    "statement": "Coffee farms with mixed native and non-native tree species show higher butterfly diversity than those with single non-native species.",
    "citations": [
      "3920"
    ]
  },
  {
    "statement": "In vineyards, grass strips between vine rows and reduced chemical management increase butterfly species richness compared to conventional management.",
    "citations": [
      "3919"
    ]
  },
  {
    "statement": "Maintaining ground cover in vineyards can reduce leafhopper pests and increase natural enemy abundance.",
    "citations": [
      "1395"
    ]
  },
  {
    "statement": "For traditional orchards, the evidence regarding conservation benefits is mixed.",
    "citations": []
  },
  {
    "statement": "One German study found similar species richness but lower abundance of butterflies and burnet moths in managed orchards compared to abandoned orchards.",
    "citations": [
      "3917"
    ]
  },
  {
    "statement": "Diversifying ground vegetation and canopy structure around woody crops increases reptile diversity and abundance in olive groves.",
    "citations": [
